import{c as s,Q as i,J as o,h as r,e as t,m as n,l,k as c}from"./chunks/framework.WgZQdPFo.js";const v=JSON.parse('{"title":"Project Philosophy","description":"Four core principles of lean, precise management accounting in OmniCraft ERP for business-minded artisans.","frontmatter":{"title":"Project Philosophy","description":"Four core principles of lean, precise management accounting in OmniCraft ERP for business-minded artisans.","order":1},"headers":[],"relativePath":"docs/introduction.md","filePath":"docs/introduction.md","lastUpdated":1794188933000}'),d={name:"docs/introduction.md"},u={id:"project-philosophy",tabindex:"-1"};function p(h,e,m,f,g,y){const a=i("DocIcon");return o(),r("div",null,[t("h1",u,[n(a,{name:"philosophy"}),e[0]||(e[0]=l(" Project Philosophy ",-1)),e[1]||(e[1]=t("a",{class:"header-anchor",href:"#project-philosophy","aria-label":'Permalink to "<DocIcon name="philosophy" /> Project Philosophy"'},"​",-1))]),e[2]||(e[2]=c('<p><strong>OmniCraft ERP</strong> is designed for artisans, makers, and small production workshops. Traditional accounting software is engineered around statutory tax requirements: it is burdened with endless primary forms, rigid charts of accounts, and distracts from hands-on work at the workbench.</p><p>At the core of the system lies engineering pragmatism: accounting must serve your craft, require minimal effort, and honestly reflect your true business profit.</p><hr><h2 id="four-core-principles-of-omnicraft-erp" tabindex="-1">Four Core Principles of OmniCraft ERP <a class="header-anchor" href="#four-core-principles-of-omnicraft-erp" aria-label="Permalink to &quot;Four Core Principles of OmniCraft ERP&quot;">​</a></h2><h3 id="_1-automation-instead-of-bookkeeping" tabindex="-1">1. Automation Instead of Bookkeeping <a class="header-anchor" href="#_1-automation-instead-of-bookkeeping" aria-label="Permalink to &quot;1. Automation Instead of Bookkeeping&quot;">​</a></h3><p>You do not need to reconcile debits and credits or assemble financial statements by hand. Actionable analytics emerge naturally from everyday workshop operations:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Purchasing:</strong> log material expenses for leather, wood, or metal—the batch is instantly placed into inventory, and freight charges automatically distribute into the unit cost of every decimeter or kilogram.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Production:</strong> materials are deducted using Moving Average Cost (MAC), preserving accurate product cost even amid supplier price spikes.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Shipment:</strong> finished goods leave the warehouse via FIFO, revenue is logged into the ledger, and the system immediately calculates your net unit profit margin.</div></li></ul><div class="info custom-block"><p class="custom-block-title">Continuous Accounting Principle</p><p>The system eliminates duplicate work. You record the physical event (received raw stock, cut a batch, handed an order to a client)—stock balances, cash ledgers, and equity update instantly.</p></div><h3 id="_2-mixed-finances-without-bureaucracy" tabindex="-1">2. Mixed Finances Without Bureaucracy <a class="header-anchor" href="#_2-mixed-finances-without-bureaucracy" aria-label="Permalink to &quot;2. Mixed Finances Without Bureaucracy&quot;">​</a></h3><p>Textbooks insist on a rigid separation between personal money and workshop cash. But in a small studio, this leads to needless friction: glues and hardware are often bought with a personal debit card, while product sales revenue is spent on family groceries.</p><p>OmniCraft ERP embraces mixed financial flows as standard reality:</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Log only business events:</strong> materials, machinery, workshop rent, and sales revenue. No need to create fictitious transfers or clutter your database with personal household expenses.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>A cash deficit reflects your investment:</strong> a negative balance in your Cash Flow Ledger simply means operations are temporarily running on your personal capital. When cash flow crosses into positive territory, the project has fully paid back your initial investment and started generating net profit.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Mathematical calculation rigor:</strong> item unit costs, your hourly return on labor, and overall workshop assets remain mathematically exact, regardless of which card paid the supplier.</div></li></ul><div class="tip custom-block"><p class="custom-block-title">Seamless Transition to Separate Accounts</p><p>If your workshop establishes a dedicated commercial account or company debit card later, the system is ready without reconfiguration. Simply select standard cash flow categories: <strong>“Business Funding (Investment)”</strong> and <strong>“Personal Withdrawal (Profit Payout)”</strong>.</p></div><h3 id="_3-asset-balance-and-real-financial-performance" tabindex="-1">3. Asset Balance and Real Financial Performance <a class="header-anchor" href="#_3-asset-balance-and-real-financial-performance" aria-label="Permalink to &quot;3. Asset Balance and Real Financial Performance&quot;">​</a></h3><p>Purchasing a Japanese hand plane, a laser cutter, or a kiln reduces your bank account balance, but your venture&#39;s wealth has not disappeared—liquid cash simply converts into dependable workshop machinery.</p><p>Your balance sheet is compiled continuously in real time:</p><div class="craft-callout craft-callout-info"><div class="callout-header">Workshop Net Assets Formula (Equity)</div><p><strong>Equity</strong> = Net Equipment Value (after depreciation) + Raw Materials Stock (at MAC) + Finished Inventory (at cost) + Liquid Bank Balances − Debts and Liabilities.</p></div><h4 id="the-triad-of-financial-statements" tabindex="-1">The Triad of Financial Statements <a class="header-anchor" href="#the-triad-of-financial-statements" aria-label="Permalink to &quot;The Triad of Financial Statements&quot;">​</a></h4><p>Three fundamental reports complement each other, preventing cash crunches and false illusions of success:</p><div class="comparison-matrix-wrapper"><table class="craft-comparison-table"><thead><tr><th style="width:24%;">Report</th><th style="width:32%;">Core Question</th><th style="width:44%;">Practical Meaning at the Workbench</th></tr></thead><tbody><tr><td><strong>Cash Flow</strong><br><small style="color:var(--vp-c-text-3);">Cash Movements</small></td><td><em>Are funds available right now?</em></td><td>Tracks physical cash and bank transfers. Helps you spot cash flow shortfalls early and avoid running out of money for rent or payroll.</td></tr><tr><td><strong>P&amp;L (Income Statement)</strong><br><small style="color:var(--vp-c-text-3);">Financial Result</small></td><td><em>Is what you are doing profitable?</em></td><td>Balances total revenue against complete operating expenses (including tool depreciation, consumed stock, and taxes). Proves whether your efforts are truly paying off.</td></tr><tr><td><strong>Balance Sheet</strong><br><small style="color:var(--vp-c-text-3);">Net Assets</small></td><td><em>What is your entire business worth?</em></td><td>Aggregates physical assets (tools, materials, finished stock) minus liabilities. Demonstrates whether workshop equity is genuinely growing year over year.</td></tr></tbody></table></div><div class="tip custom-block"><p class="custom-block-title">Automated Snapshot Archive</p><p>The system periodically records historical snapshots of vital metrics. This enables tracking performance over time: assessing seasonal monthly fluctuations alongside long-term strategic equity growth.</p></div><h3 id="_4-private-ai-assistance-with-zero-intermediaries-byok" tabindex="-1">4. Private AI Assistance with Zero Intermediaries (<code>BYOK</code>) <a class="header-anchor" href="#_4-private-ai-assistance-with-zero-intermediaries-byok" aria-label="Permalink to &quot;4. Private AI Assistance with Zero Intermediaries (`BYOK`)&quot;">​</a></h3><p>Built-in artificial intelligence operates with zero data brokering: the <strong><code>BYOK</code></strong> (<em>Bring Your Own Key</em>) architecture.</p><ul class="craft-feature-list"><li><span class="craft-list-bullet">✓</span><div><strong>Direct connection without proxy servers:</strong> requests travel directly from your machine to AI providers (`OpenAI`, `DeepSeek`, `Google Gemini`, `OpenRouter`) or execute locally through an offline `Ollama` instance. Recipes, cost calculations, and client details never reach developer servers.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>On-the-job assistants:</strong> contextual action buttons are built directly into active forms—batch cost structure reviews in the calculator, quality checkpoints on the workbench, and automated description generation for inventory items.</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Human supervision:</strong> the sliding sidebar analyzes the active workspace and batch context, but makes no changes to your database without your explicit authorization (<em>Human-in-the-Loop</em>).</div></li><li><span class="craft-list-bullet">✓</span><div><strong>Standardized Model Context Protocol (`MCP`):</strong> native local protocol support connects OmniCraft ERP directly to external engineering environments (`Cursor`, `Claude Desktop`, `Antigravity`).</div></li></ul>',24))])}const k=s(d,[["render",p]]);export{v as __pageData,k as default};
